SELECT (SELECT id FROM public.import_runs WHERE pipeline_version = 'vision-quality-gated-batch-0454-0458-v1' ORDER BY started_at DESC LIMIT 1), b.id, 454, 'educational'::page_kind, 'মধুসূদন দত্ত ♦ জন্মিলে মরিতে হবে অমর কে কোথা কবে? ♦ হে বঙ্গ, ভাণ্ডারে তব বিবিধ রতন, .......... পর ধন লোভে মত্ত ♦ সতত হে নদ, তুমি পড় মোর মনে সতত তোমার কথা ভাবি এ বিরলে। চণ্ডীদাস ♦ শুনহ মানুষ ভাই সবার উপর মানুষ সত্য তাহার উপর নাই। কৃষ্ণচন্দ্র মজুমদার ♦ যে জন দিবসে মনের হরষে জ্বালায় মোমের বাতি। ♦ কাঁটা হেরি ক্ষান্ত কেন কমল তুলিতে দুঃখ বিনা সুখ লাভ হয় কি মহীতে? দ্বিজেন্দ্রলাল রায় ♦ ধনধান্য পুষ্পভরা আমাদের এই বসুন্ধরা তাহার মাঝে আছে দেশ এক সকল দেশের সেরা। মুকুন্দরাম চক্রবর্তী ♦ অভাগা যদ্যপি চায় সাগর শুকায়ে যায়। সত্যেন্দ্রনাথ দত্ত ♦ কালো আর ধলো বাহিরে কেবল ভিতরে সবার সমান রাঙা। ♦ মধুর চেয়ে আছে মধু সে আমার দেশের মাটি আমার দেশের পায়ের ধুলো খাঁটি সোনার চাইতে খাঁটি। মদনমোহন তর্কালঙ্কার ♦ পাখি সব করে রব রাতি পোহাইল কাননে কুসুম কলি সকলি ফুটিল। ♦ সকালে উঠিয়া আমি মনে মনে বলি সারাদিন আমি যেন ভাল হয়ে চলি। কামিনী রায় ♦ সকলের তরে সকলে আমরা প্রত্যেকে মোরা পরের তরে ♦ পরের কারণে স্বার্থ দিয়া বলি এ জীবন মন সকলি দাও। ♦ সংশয়ে সংকল্প সদা টলে পাছে লোকে কিছু বলে। বেগম রোকেয়া ♦ বিবাহ হইলে বালিকা ভাবে, যাহা হোক, পড়া হইতে রক্ষা পাওয়া গেল। ♦ স্বামী যখন পৃথিবী হইতে সূর্য ও নক্ষত্রের দূরত্ব মাপেন, স্ত্রী তখন বালিশের ওয়াড়ের দৈর্ঘ্য-প্রস্থ মাপেন। সুফিয়া কামাল ♦ হে কবি, নীরব কেন ফাগুন যে এসেছে ধরায় ♦ জন্মেছি মাগো তোমার কোলেতে মরি যেন এই দেশে। দাউদ হায়দার ♦ জন্মই আমার আজন্ম পাপ। সুকান্ত ভট্টাচার্য ♦ এ বিশ্বকে এ শিশুর বাসযোগ্য করে যাব আমি। ♦ ক্ষুধার রাজ্যে পৃথিবী গদ্যময় পূর্ণিমা চাঁদ যেন ঝলসানো রুটি। ♦ সাবাস বাংলাদেশ! এ পৃথিবী অবাক তাকিয়ে রয়: জ্বলে-পুড়ে মরে ছারখার তবু মাথা নোয়াবার নয়। অতুলপ্রসাদ সেন ♦ মোদের গরব, মোদের আশা আ-মরি বাংলা ভাষা। নির্মলেন্দু গুণ ♦ যুদ্ধ মানে শত্রু শত্রু খেলা।', 'বাংলা সাহিত্য', 'কবি ও সাহিত্য উদ্ধৃতি', 'high'::confidence_level, 'vision_ocr_with_image_grounded_review', 'gemini-3-flash-preview', 'Quality-gated batch: source-preserving OCR, spelling review, semantic tagging, and external-verifica