SELECT (SELECT id FROM public.import_runs WHERE pipeline_version = 'vision-quality-gated-batch-0454-0458-v1' ORDER BY started_at DESC LIMIT 1), b.id, 456, 'mixed'::page_kind, 'কতিপয় ঐতিহাসিক প্রেক্ষাপট ক্ষুদিরামের ফাঁসির আদেশ হয়ে যাওয়ার পর রংপুরের উকিল সতীশচন্দ্র চক্রবর্তী ক্ষুদিরামকে জিজ্ঞেস করেছিলেন, “তোমার শেষ ইচ্ছা কি?” ক্ষুদিরাম বলেছিল, “আমিতো মেদিনীপুরের ছেলে আমি মেদিনীপুর যেতে চাই, মেদিনীপুর বাসীদের একটু দেখতে চাই”। ক্ষুদিরামের শেষ ইচ্ছা পূরণ করা হয়নি। ১৯০৮ সালে মঙ্গলবার ভোরে ক্ষুদিরামের ফাঁসি হয়ে যাওয়ার পর পিতাম্বর সেন লিখেছিলেন- একবার বিদায় দে মা ঘুরে আসি আমি হাসি হাসি পরবো ফাঁসি দেখবে ভারতবাসী বঙ্গভঙ্গের সমর্থন করতো মুসলমানরা আর বিরোধিতা করেছিল হিন্দুরা। বঙ্গভঙ্গের প্রেক্ষিতে ১৯০৫ সালে অত্যন্ত ব্যথিত হৃদয়ে রবীন্দ্রনাথ ঠাকুর লিখেছিলেন- আমার সোনার বাংলা আমি তোমায় ভালোবাসি রবীন্দ্রনাথ যখন ১৯১৩ সালে নোবেল পুরস্কার পেলেন, বাংলা সাহিত্যভাণ্ডারের আন্তর্জাতিক সম্মাননা মিললো, শরীয়তপুরের অতুল প্রসাদ সেন তখন গাইলেন- মোদের গরব মোদের আশা আ-মরি বাংলা ভাষা ১৯৪৩ এর দুর্ভিক্ষে প্রায় ৫০ লক্ষ লোক মারা গেল। জয়নুল আবেদীন বিখ্যাত হলেন একটা চিত্রকর্ম এঁকে- ম্যাডোনা-৪৩ এই ৪৩; ১৯৪৩ এর ৪৩ এই মন্বন্তরের প্রেক্ষিতেই নুরুল মোমেন লিখেছিলেন বিখ্যাত নাটক “নেমেসিস” সত্যজিৎ রায় নির্মাণ করেছিলেন বিখ্যাত চলচ্চিত্র “অশনি সংকেত” পাকিস্তান থেকে যখন আমরা মুক্ত হলাম, পাকিস্তান নামক রাষ্ট্র হতে বিদায় নিলাম শেখ আজিজুর রহমান ছদ্মনামে লেখা ছোট সাইজের মানুষ শওকত ওসমান লিখলেন বিখ্যাত উপন্যাস- জাহান্নাম হইতে বিদায় আইয়ুব খান আমাদের শাসন করেছেন ১৯৫৮-১৯৬৯ সাল পর্যন্ত। এই সময়টাতে আমাদের জোর করে ক্রীতদাস বানিয়ে পিটিয়ে হাসাতে চেয়েছেন। বহির্বিশ্বে প্রমাণ করার চেষ্টা করেছেন এরা হাসছে, এরা ভালো আছে। শওকত ওসমান আইয়ুব খানের চরিত্রটাই নিয়ে আসলেন রূপক অর্থে বিখ্যাত এক উপন্যাসে। আইয়ুব খানের শাসন নিয়ে শওকত ওসমান লিখলেন বিখ্যাত উপন্যাস- ক্রীতদাসের হাসি ৩৯৯', 'কতিপয় ঐতিহাসিক প্রেক্ষাপট', 'ঐতিহাসিক ও সাংস্কৃতিক প্রেক্ষাপট', 'high'::confidence_level, 'vision_ocr_with_image_grounded_review', 'gemini-3-flash-preview', 'Quality-gated batch: source-preserving OCR, spelling review, semantic tagging, and external-verification ledger recorded.', '{"source_image_sha256":"8121f742f2de66ac8194ec598ebd6e189ffb7a08d84d46472d3f758967ecac73","extraction_model":"gemini-3-flash-preview","review_status":"accepted","corrections":[],"unresolved_spans":[],"accepted_content_tags":["topic_heading","fact","misc"],"external_verification_report":"/home/ubuntu/dontonyo/reports/batch-0454-0458_external_verification.md","physical_source_page":456,"printed_book_page":399,"page_kind":"mixed"}'::jsonb
