SELECT (SELECT id FROM public.import_runs WHERE pipeline_version = 'vision-quality-gated-batch-0454-0458-v1' ORDER BY started_at DESC LIMIT 1), b.id, 457, 'educational'::page_kind, '৬৯ এর গণঅভ্যুত্থানে ২০ জানুয়ারি গুলি করে হত্যা করা হলো নরসিংদীর ছেলে আসাদকে। আসাদের লাশ নিয়ে মিছিল হলো, আসাদের রক্তমাখা শার্ট নিয়ে মিছিল হলো। নরসিংদীরই আরেক কবি শামসুর রাহমান লিখলেন সেই বিখ্যাত কবিতা- আসাদের শার্ট ১৯৩৭ সালে হিটলার স্পেনে আক্রমণ করে স্পেনের গোয়ের্নিকা শহরটি ধ্বংস করে। এই ধ্বংস যজ্ঞের চিত্রকর্ম আঁকেন স্পেনের মানবতাবাদী বিখ্যাত চিত্রকর পাবলো পিকাসো। যা বিখ্যাত চিত্রকর্ম “গোয়ের্নিকা”। আমেরিকা ১৭৭৬ সালে স্বাধীনতা লাভ করে ব্রিটেনের কাছ থেকে। আমেরিকার স্বাধীনতায় প্রত্যক্ষ সহযোগিতা করে ফ্রান্স। আমেরিকার স্বাধীনতার একশত বছর পূর্তিতে ফ্রান্স আমেরিকার জন্য উপহার পাঠায় যেটি “স্ট্যাচু অব লিবার্টি”। স্পেনের গোয়ের্নিকা শহর ধ্বংসের প্রেক্ষিতে পাবলো পিকাসো এঁকেছিলেন “গোয়ের্নিকা” চিত্রকর্মটি যেখানে মানুষ ও পশুর দুর্ভোগ ফুটে ওঠে ক্ষুদিরামকে ফাঁসি দেওয়ার প্রেক্ষিতে পীতাম্বর সেন লিখেছিলেন গান “একবার বিদায় দে মা ঘুরে আসি আমি হাসি হাসি পরবো ফাঁসি” ব্রিটেন হতে আমেরিকার স্বাধীনতার একশত বছর পূর্তিতে ফ্রান্স ১৮৮৬ সালে আমেরিকাকে উপহার পাঠায় “স্ট্যাচু অব লিবার্টি” Zubair''s GK - 400', 'কতিপয় ঐতিহাসিক প্রেক্ষাপট', 'ঐতিহাসিক ও সাংস্কৃতিক প্রেক্ষাপট', 'high'::confidence_level, 'vision_ocr_with_image_grounded_review', 'gemini-3-flash-preview', 'Quality-gated batch: source-preserving OCR, spelling review, semantic tagging, and external-verification ledger recorded.', '{"source_image_sha256":"caf89f1f49e754bae59883780dae90aad4cf18c8492d356d262452455dc4bb7a","extraction_model":"gemini-3-flash-preview","review_status":"accepted_with_flags","corrections":[{"transcribed_text":"গুয়ের্নিকা","source_reading":"গোয়ের্নিকা","reason":"Spelling correction based on the visual source text which uses the ''o'' vowel marker."}],"unresolved_spans":[],"accepted_content_tags":["fact","map_caption","misc"],"external_verification_report":"/home/ubuntu/dontonyo/reports/batch-0454-0458_external_verification.md","physical_source_page":457,"printed_book_page":400,"page_kind":"educational"}'::jsonb
