('456', 'historical-context', 'কতিপয় ঐতিহাসিক প্রেক্ষাপট', 'আইয়ুব খান আমাদের শাসন করেছেন ১৯৫৮-১৯৬৯ সাল পর্যন্ত। এই সময়টাতে আমাদের জোর করে ক্রীতদাস বানিয়ে পিটিয়ে হাসাতে চেয়েছেন। বহির্বিশ্বে প্রমাণ করার চেষ্টা করেছেন এরা হাসছে, এরা ভালো আছে। শওকত ওসমান আইয়ুব খানের চরিত্রটাই নিয়ে আসলেন রূপক অর্থে বিখ্যাত এক উপন্যাসে। আইয়ুব খানের শাসন নিয়ে শওকত ওসমান লিখলেন বিখ্যাত উপন্যাস- ক্রীতদাসের হাসি', 'আইয়ুব খান আমাদের শাসন করেছেন ১৯৫৮-১৯৬৯ সাল পর্যন্ত। এই সময়টাতে আমাদের জোর করে ক্রীতদাস বানিয়ে পিটিয়ে হাসাতে চেয়েছেন। বহির্বিশ্বে প্রমাণ করার চেষ্টা করেছেন এরা হাসছে, এরা ভালো আছে। শওকত ওসমান আইয়ুব খানের চরিত্রটাই নিয়ে আসলেন রূপক অর্থে বিখ্যাত এক উপন্যাসে। আইয়ুব খানের শাসন নিয়ে শওকত ওসমান লিখলেন বিখ্যাত উপন্যাস- ক্রীতদাসের হাসি', '3', 'medium', 'a5d6f0f12534315d976bfc1a9423c9509df5677f7faf35bdd2758dc32fdf8408', 'Source-attributed content retained with its source page and audit status.'),
('457', 'historical-context', 'উনসত্তরের গণঅভ্যুত্থান ও শহীদ আসাদ', 'আমানউল্লাহ মোহাম্মদ আসাদুজ্জামান ২০ জানুয়ারি ১৯৬৯ সালে ঢাকা শহরে ছাত্র মিছিলে নেতৃত্ব দেওয়ার সময় পুলিশের গুলিতে নিহত হন; তাঁর রক্তমাখা শার্ট প্রতীকে পরিণত হয় এবং শামসুর রাহমান ‘আসাদের শার্ট’ কবিতা লেখেন।', '৬৯ এর গণঅভ্যুত্থানে ২০ জানুয়ারি গুলি করে হত্যা করা হলো নরসিংদীর ছেলে আসাদকে। আসাদের লাশ নিয়ে মিছিল হলো, আসাদের রক্তমাখা শার্ট নিয়ে মিছিল হলো। নরসিংদীরই আরেক কবি শামসুর রাহমান লিখলেন সেই বিখ্যাত কবিতা- আসাদের শার্ট', '5', 'high', '95d12a5abd51d7b0ee413b13f2e06166b0946ef0ce6ad0750dc2edc9375e7a41', 'Externally corroborated; source wording is retained in source_excerpt.'),
('457', 'historical-context', 'পাবলো পিকাসোর ‘গের্নিকা’', '১৯৩৭ সালের ২৬ এপ্রিল স্পেনের বাস্ক শহর গের্নিকায় জার্মান ও ইতালীয় বাহিনীর বোমাবর্ষণের প্রেক্ষিতে পাবলো পিকাসো ‘গের্নিকা’ চিত্রকর্মটি আঁকেন।', '১৯৩৭ সালে হিটলার স্পেনে আক্রমণ করে স্পেনের গোয়ের্নিকা শহরটি ধ্বংস করে। এই ধ্বংস যজ্ঞের চিত্রকর্ম আঁকেন স্পেনের মানবতাবাদী বিখ্যাত চিত্রকর পাবলো পিকাসো। যা বিখ্যাত চিত্রকর্ম ‘গোয়ের্নিকা’।', '4', 'high', '4d879a4b329cc2629d34e030a66f6caaae8250a41fd0e715f6cd4ca28778a5d2', 'Externally corroborated; source wording is retained in source_excerpt.'),
('457', 'historical-context', 'স্ট্যাচু অব লিবার্টি', 'ফরাসি জনগণের উপহার ‘স্ট্যাচু অব লিবার্টি’ যুক্তরাষ্ট্রের স্বাধীনতার শতবার্ষিকী ও দুই দেশের বন্ধুত্ব স্মরণে প্রস্তাবিত হয়; এটি ২৮ অক্টোবর ১৮৮৬ সালে উন্মোচিত হয়।', 'আমেরিকার স্বাধীনতার একশত বছর পূর্তিতে ফ্রান্স আমেরিকার জন্য উপহার পাঠায় যেটি ‘স্ট্যাচু অব লিবার্টি’। ... ফ্রান্স ১৮৮৬ সালে আমেরিকাকে উপহার পাঠায় ‘স্ট্যাচু অব লিবার্টি’।', '4', 'high', '64dd7911daa5950838b7462c1ed46407f2916850bdfb20e19f6df1e28d850180', 'Externally corroborated; source wording is retained in source_excerpt.')
)
INSERT INTO public.gk_facts (book_id, chapter_id, topic_id, title, fact_text, explanation, source_page, source_section, source_excerpt, importance, confidence, canonical_hash)
SELECT b.id, c.id, t.id, d.title, d.fact_text, d.explanation, d.source_page::integer, d.title, d.source_excerpt, d.importance::smallint, d.confidence::confidence_level, d.canonical_hash
FROM data d
JOIN public.books b ON b.title = 'Jubayer''s GK'
JOIN public.chapters c ON c.book_id = b.id AND c.slug = CASE WHEN d.topic_slug = 'bangla-literature' THEN 'bangla-literature' ELSE 'historical-context' END
JOIN public.topics t ON t.chapter_id = c.id AND t.slug = CASE WHEN d.topic_slug = 'bangla-literature' THEN 'literary-quotations' ELSE 'historical-context' END
ON CONFLICT (canonical_hash) DO UPDATE SET fact_text = EXCLUDED.fact_text, explanation = EXCLUDED.explanation, confidence = EXCLUDED.confidence, source_excerpt = EXCLUDED.source_excerpt;
